CREATE TABLE "Music_Song" (
 "id" TEXT NOT NULL PRIMARY KEY, "slug" TEXT NOT NULL UNIQUE, "title" TEXT NOT NULL, "artist" TEXT NOT NULL, "genre" TEXT NOT NULL, "key" TEXT NOT NULL, "bpm" INTEGER NOT NULL, "time_signature" TEXT NOT NULL, "chord_progression" TEXT[] NOT NULL, "notation_json" JSONB NOT NULL, "lyrics_json" JSONB, "isukuti_pattern" JSONB, "audio_url" TEXT, "content_kind" TEXT NOT NULL DEFAULT 'ORIGINAL', "source_note" TEXT NOT NULL, "reference_url" TEXT
);
CREATE TABLE "Music_Project" (
 "id" TEXT NOT NULL PRIMARY KEY, "student_id" INTEGER NOT NULL REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE, "title" TEXT NOT NULL, "song_id" TEXT REFERENCES "Music_Song"("id") ON DELETE SET NULL ON UPDATE CASCADE, "bpm" INTEGER NOT NULL DEFAULT 90, "time_signature" TEXT NOT NULL DEFAULT '6/8', "tracks_json" JSONB NOT NULL, "mp3_url" TEXT, "status" TEXT NOT NULL DEFAULT 'DRAFT', "submitted_at" TIMESTAMP(3), "reviewed_by" INTEGER REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE, "reviewed_at" TIMESTAMP(3), "score" DOUBLE PRECISION, "review_comment" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL
);
CREATE INDEX "Music_Project_student_id_updated_at_idx" ON "Music_Project"("student_id","updated_at");
CREATE INDEX "Music_Project_status_submitted_at_idx" ON "Music_Project"("status","submitted_at");
